--
-- Table structure for table `mw_user`
--

DROP TABLE IF EXISTS `mw_user`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `mw_user` (
  `uid` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT '用户id',
  `username` varchar(255) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '用户账户(跟accout一样)',
  `password` varchar(255) DEFAULT NULL COMMENT '用户密码（跟pwd）',
  `real_name` varchar(25) CHARACTER SET utf8mb4 DEFAULT '' COMMENT '真实姓名',
  `birthday` int(11) DEFAULT '0' COMMENT '生日',
  `card_id` varchar(20) DEFAULT '' COMMENT '身份证号码',
  `mark` varchar(255) DEFAULT '' COMMENT '用户备注',
  `partner_id` int(11) DEFAULT '0' COMMENT '合伙人id',
  `group_id` int(11) DEFAULT '0' COMMENT '用户分组id',
  `nickname` varchar(100) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '用户昵称',
  `avatar` varchar(256) DEFAULT NULL COMMENT '用户头像',
  `phone` char(15) DEFAULT NULL COMMENT '手机号码',
  `add_ip` varchar(100) DEFAULT '' COMMENT '添加ip',
  `create_time` datetime DEFAULT NULL COMMENT '添加时间',
  `update_time` datetime DEFAULT NULL COMMENT '最后一次登录时间',
  `last_ip` varchar(100) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '最后一次登录ip',
  `now_money` decimal(8,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '用户余额',
  `brokerage_price` decimal(8,2) NOT NULL DEFAULT '0.00' COMMENT '佣金金额',
  `integral` decimal(8,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '用户剩余积分',
  `sign_num` int(11) NOT NULL DEFAULT '0' COMMENT '连续签到天数',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1为正常，0为禁止',
  `level` tinyint(2) unsigned NOT NULL DEFAULT '0' COMMENT '等级',
  `level_pdd` tinyint(2) unsigned NOT NULL DEFAULT '0' COMMENT '拼多多会员等级',
  `level_jd` tinyint(2) unsigned NOT NULL DEFAULT '0' COMMENT '京东会员等级',
  `level_dy` tinyint(2) unsigned NOT NULL DEFAULT '0' COMMENT '抖音会员等级',
  `level_vip` tinyint(2) unsigned NOT NULL DEFAULT '0' COMMENT '唯品会会员等级',
  `spread_uid` bigint(20) unsigned DEFAULT '0' COMMENT '推广元id',
  `spread_time` datetime DEFAULT NULL COMMENT '推广员关联时间',
  `spread_update` tinyint(1) NOT NULL DEFAULT '0' COMMENT '被用于会员升级 1已使用 0未使用',
  `user_type` varchar(32) NOT NULL COMMENT '用户类型',
  `is_promoter` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '是否为推广员',
  `pay_count` int(11) unsigned DEFAULT '0' COMMENT '用户购买次数',
  `spread_count` int(11) DEFAULT '0' COMMENT '下级人数',
  `addres` varchar(255) NOT NULL DEFAULT '' COMMENT '详细地址',
  `adminid` int(11) unsigned DEFAULT '0' COMMENT '管理员编号 ',
  `login_type` varchar(36) NOT NULL DEFAULT '' COMMENT '用户登陆类型，h5,wechat,routine',
  `wx_profile` json DEFAULT NULL COMMENT '微信用户json信息',
  `ali_profile` json DEFAULT NULL COMMENT '微信用户json信息',
  `additional_no` varchar(36) DEFAULT NULL,
  `code` varchar(16) CHARACTER SET utf8mb4 NOT NULL COMMENT '邀请码',
  `expired` datetime DEFAULT NULL COMMENT '会员到期时间',
  `expired_jd` datetime DEFAULT NULL COMMENT '京东会员到期时间',
  `expired_pdd` datetime DEFAULT NULL COMMENT '拼多多会员到期时间',
  `expired_dy` datetime DEFAULT NULL COMMENT '抖音会员到期时间',
  `expired_vip` datetime DEFAULT NULL COMMENT '唯品会会员到期时间',
  `change_word` tinyint(1) DEFAULT '0' COMMENT '0-默认 1-第一次修改 2-第二次修改 3-第三次修改',
  `tb_pid` varchar(100) DEFAULT NULL COMMENT '淘宝pid',
  `jd_pid` varchar(100) DEFAULT NULL COMMENT '京东pid',
  `hb_pool` double DEFAULT '0' COMMENT '拆红包佣金池',
  `pdd_pid` varchar(100) DEFAULT NULL COMMENT '拼多多pid',
  `wechat_open_id` varchar(100) DEFAULT NULL COMMENT '微信公众号openId',
  `is_del` tinyint(1) DEFAULT '0',
  PRIMARY KEY (`uid`) USING BTREE,
  UNIQUE KEY `username` (`username`) USING BTREE,
  KEY `spreaduid` (`spread_uid`) USING BTREE,
  KEY `level` (`level`) USING BTREE,
  KEY `status` (`status`) USING BTREE,
  KEY `is_promoter` (`is_promoter`) USING BTREE,
  KEY `phone` (`phone`) USING BTREE,
  KEY `wechat_open_id` (`wechat_open_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='用户表';
/*!40101 SET character_set_client = @saved_cs_client */;

